/*
 * cyd_bg.h -- odo-miner's honeycomb backdrop, embedded.
 *
 * THE ACTUAL IMAGE, not an approximation. This is
 * odo-miner-cyclonev/linux/overlay/etc/odo-ui/bg.png, which is already exactly
 * 320x240 -- the CYD's native size in landscape -- converted to RGB565 with
 * the same 245/255 knock-down odo_ui.c applies via gfx_background(fb, path,
 * 10). No scaling, so it is pixel-for-pixel what the other panel shows.
 *
 * I first drew a hex grid procedurally instead, on the grounds that 150KB of
 * flash was too much for a texture. That was wrong: this firmware uses 26% of
 * 1.3MB, so the image costs headroom nobody needs, and "close enough" on the
 * one element covering every screen is exactly what made the two panels look
 * like different products.
 *
 * Generated -- do not edit. Regenerate from bg.png if the artwork changes.
 */
